			return fmt.Errorf("import %s: %w", imp.Name(), runErr)
		}
		fmt.Fprintf(w, "  Imported %d turn(s) from %d %s session(s) (%d already imported).\n",
			res.TurnsImported, res.SessionsScanned, imp.Name(), res.TurnsSkipped)
	}
	return nil
}

